import json
from typing import Optional

HOLD_MUSIC_URI = "gs://ss-hold-music-2026/KennyG_16k_mono.wav"

def after_model_callback(callback_context: CallbackContext, llm_response: LlmResponse) -> Optional[LlmResponse]:
    parts = list(llm_response.content.parts)
    for index, part in enumerate(parts):
        if getattr(part, 'function_call', None):
            audio_directive = Part.from_json(data=json.dumps({
                "audioUri": HOLD_MUSIC_URI,
                "cancellable": True,
                "interruptable": True
            }))
            return LlmResponse.from_parts(parts=parts[:index] + [audio_directive] + parts[index:])
    return None
